import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code for clamp
clamp_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void clamp_kernel(const float* in, float* out, float min_val, float max_val, int total_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_size) {
        float val = in[idx];
        if (val < min_val) val = min_val;
        if (val > max_val) val = max_val;
        out[idx] = val;
    }
}

torch::Tensor custom_clamp_cuda(torch::Tensor input, float min_val, float max_val) {
    auto out = torch::zeros_like(input);
    int total_size = input.numel();
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    clamp_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        min_val,
        max_val,
        total_size
    );

    return out;
}
"""

clamp_cpp_source = r"torch::Tensor custom_clamp_cuda(torch::Tensor input, float min_val, float max_val);"

clamp_op = load_inline(
    name="custom_clamp",
    cpp_sources=clamp_cpp_source,
    cuda_sources=clamp_source,
    functions=["custom_clamp_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[],
)

# Custom CUDA code for multiply
multiply_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void multiply_kernel(const float* in, float* out, float factor, int total_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_size) {
        out[idx] = in[idx] * factor;
    }
}

torch::Tensor custom_multiply_cuda(torch::Tensor input, float factor) {
    auto out = torch::zeros_like(input);
    int total_size = input.numel();
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    multiply_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        factor,
        total_size
    );

    return out;
}
"""

multiply_cpp_source = r"torch::Tensor custom_multiply_cuda(torch::Tensor input, float factor);"

multiply_op = load_inline(
    name="custom_multiply",
    cpp_sources=multiply_cpp_source,
    cuda_sources=multiply_source,
    functions=["custom_multiply_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, pool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding
        )
        self.avg_pool = nn.AvgPool3d(pool_kernel_size)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.clamp_op = clamp_op
        self.multiply_op = multiply_op

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.avg_pool(x)
        x = self.clamp_op.custom_clamp_cuda(x, self.clamp_min, self.clamp_max)
        x = torch.softmax(x, dim=1)
        x = self.multiply_op.custom_multiply_cuda(x, 2.0)
        return x
